// ?????? - GitHub CDN ??????????? (sisjzknxhnsnejxn-cmyk/Time-Back)
(async () => {
  const repo = 'sisjzknxhnsnejxn-cmyk/Time-Back';
  const file = 'dist/' + encodeURIComponent('时空回溯系统') + '/index.js';
  let ref = '34427dc';
  try {
    const res = await fetch(`https://api.github.com/repos/${repo}/commits/main`, { cache: 'no-store' });
    if (res.ok) {
      const data = await res.json();
      if (data && data.sha) ref = data.sha.slice(0, 7);
    }
  } catch (_) {}
  try {
    await import(`https://testingcf.jsdelivr.net/gh/${repo}@${ref}/${file}`);
  } catch (_) {
    await import(`https://cdn.jsdelivr.net/gh/${repo}@${ref}/${file}`);
  }
})();
